// Listen to living entity events
MinecraftForge.EVENT_BUS.addListener(this::onLivingHurt);
MinecraftForge.EVENT_BUS.addListener(this::onLivingDeath);
MinecraftForge.EVENT_BUS.addListener(this::onLivingUseItem);

private void onLivingHurt(LivingHurtEvent event) {
    Entity source = event.getSource().getEntity();
    float damage = event.getAmount();

    // Example: Double damage from fire
    if (event.getSource().isFire()) {
        event.setAmount(damage * 2);
    }

    // Example: Prevent player from taking damage
    if (event.getEntityLiving() instanceof Player player && player.isCreative()) {
        event.setCanceled(true);
    }
}

private void onLivingDeath(LivingDeathEvent event) {
    EntityLiving victim = event.getEntityLiving();
    DamageSource source = event.getSource();

    // Example: Drop custom loot
    if (victim instanceof EntityZombie) {
        victim.dropAt(new ItemStack(Items.DIAMOND), true);
    }
}

